mapper.delete:
DELETE FROM sys99_print
 WHERE sys99_company_id      = #{companyId}
   AND sys99_person_id       = #{printPersonId}
   AND sys99_window_class_nm = #{windowClassName}

mapper.select:
SELECT apr19_relate_stamp_id AS relate_stamp_id , apr19_corp_doc_id AS corp_doc_id , apr19_call_date AS call_date , apr19_call_emp_nm AS call_emp_name , apr19_stamp_nm AS stamp_name , apr19_stamp_cnt AS stamp_cnt , apr19_provide_co AS provide_co , apr19_purpose AS purpose , apr19_appr_cnt_str AS appr_cnt_str , apr19_stamp_date AS stamp_date , CASE WHEN COALESCE(apr19_stamp_file_cnt, 0) > 0 THEN 'O' ELSE 'X' END AS stamp_file_yn_str , apr19_confirm_date AS confirm_date , apr19_confirmer_id AS confirmer_id , apr19_confirmer_nm AS confirmer_name FROM ( SELECT apr19_relate_stamp.apr19_relate_stamp_id , apr19_relate_stamp.apr19_corp_doc_id , apr19_relate_stamp.apr19_stamp_cnt , apr19_relate_stamp.apr19_stamp_date , apr19_relate_stamp.apr19_confirmer_id , apr19_relate_stamp.apr19_confirm_date , apr17_call_date AS apr19_call_date , f_emp_kor_nm(apr17_call_emp_id) AS apr19_call_emp_nm , apr10_stamp_nm AS apr19_stamp_nm , apr17_provide_co AS apr19_provide_co , apr17_purpose AS apr19_purpose , ( SELECT count(*) FROM apr18_relate_corp_doc INNER JOIN apr01_appr ON apr01_appr_id = apr18_appr_id WHERE apr18_corp_doc_id = apr17_corp_doc_id )||' 건' AS apr19_appr_cnt_str , ( SELECT count(*) FROM apr18_relate_corp_doc INNER JOIN sys10_file ON sys10_parent_id = apr18_appr_id WHERE apr18_corp_doc_id = apr19_corp_doc_id AND sys10_stamp_yn = 'true' ) AS apr19_stamp_file_cnt , f_emp_kor_nm(apr19_confirmer_id) AS apr19_confirmer_nm FROM apr19_relate_stamp INNER JOIN apr17_corp_doc ON apr17_corp_doc_id = apr19_corp_doc_id INNER JOIN apr10_stamp ON apr10_stamp_id = apr19_stamp_id LEFT OUTER JOIN apr01_appr ON apr01_appr_id = apr19_appr_id WHERE apr17_company_id = #{companyId} AND apr17_call_date BETWEEN #{startDate} AND #{closeDate}
AND apr19_stamp_id = #{stampId}
AND ( ( apr19_appr_id IS NULL AND ( SELECT COUNT(*) FROM apr18_relate_corp_doc WHERE apr18_corp_doc_id = apr19_corp_doc_id AND apr18_appr_id IS NOT NULL ) = 0 ) /* 문서연결이 안되어 있거나, */ OR ( SELECT COUNT(*) FROM apr18_relate_corp_doc INNER JOIN apr01_appr ON apr01_appr_id = apr18_appr_id WHERE apr18_corp_doc_id = apr19_corp_doc_id AND apr01_status_cd = '30' ) != 0 /* 결재완료문서 */ OR apr01_status_cd = '30' ) ) t WHERE 1=1
AND apr19_stamp_file_cnt = 0
ORDER BY apr19_call_date DESC, apr19_corp_doc_id DESC, apr19_relate_stamp_id DESC

SELECT s.apr19_stamp_date
  FROM apr19_relate_stamp s
       INNER JOIN apr17_corp_doc a ON a.apr17_corp_doc_id = s.apr19_corp_doc_id
 WHERE s.apr19_relate_stamp_id = #{relateStampId}
   AND a.apr17_company_id      = #{companyId}

SELECT COUNT(*)
  FROM apr19_relate_stamp s
       INNER JOIN apr17_corp_doc a ON a.apr17_corp_doc_id = s.apr19_corp_doc_id
 WHERE s.apr19_relate_stamp_id = #{relateStampId}
   AND a.apr17_company_id      = #{companyId}

mapper.update:
UPDATE apr19_relate_stamp
   SET apr19_stamp_date = #{stampDate,jdbcType=DATE}
 WHERE apr19_relate_stamp_id = #{relateStampId}
   AND apr19_corp_doc_id IN ( SELECT apr17_corp_doc_id FROM apr17_corp_doc WHERE apr17_company_id = #{companyId} )

UPDATE apr19_relate_stamp
   SET apr19_confirmer_id = #{confirmerId,jdbcType=NUMERIC}
     , apr19_confirm_date = #{confirmDate,jdbcType=DATE}
 WHERE apr19_relate_stamp_id = #{relateStampId}
   AND apr19_corp_doc_id IN ( SELECT apr17_corp_doc_id FROM apr17_corp_doc WHERE apr17_company_id = #{companyId} )
